				"references": [{
					"name": "MDN Reference",
					"url": "https://developer.mozilla.org/docs/Web/HTML/Reference/Elements/base"
				}],
				"browsers": [
					"C1",
					"CA18",
					"E12",
					"FF1",
					"FFA4",
					"S3",
					"SM2"
				],
